create function pg_temp.arrive(task uuid,actor integer) returns void language plpgsql as $$declare start_at timestamptz;state text;begin
 perform pg_temp.actor(actor);select (entry->>'start')::timestamptz into start_at from jsonb_array_elements(public.read_work_order((select id from execution_ids where key='work'))->'tasks') entry where entry->>'id'=task::text;
 perform pg_sleep(greatest(0,extract(epoch from start_at-clock_timestamp()))+0.02);perform pg_temp.fc('accept_task',jsonb_build_object('task_id',task));
 foreach state in array array['mobilising','en_route','arrived'] loop perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state',state));end loop;
 perform pg_temp.fc('attendance',jsonb_build_object('task_id',task,'kind','check_in'));
end$$;
create function pg_temp.start_job(task uuid,actor integer) returns void language plpgsql as $$begin perform pg_temp.actor(actor);perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','started'));perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','in_progress'));end$$;
create function pg_temp.finish_job(task uuid,actor integer,batch uuid default null) returns void language plpgsql as $$declare response uuid;inspection uuid;begin
 response=pg_temp.checklist(task,'execution',actor);perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','work_completed'));
 perform pg_temp.actor(3);perform pg_temp.fc('review_checklist',jsonb_build_object('task_id',task,'id',response,'approve',true));perform pg_temp.fc('supervisor_verify',jsonb_build_object('task_id',task));
 inspection=pg_temp.qc('request',jsonb_build_object('task_id',task,'inspector_id','d1000000-0000-0000-0000-000000000004','scheduled_at',clock_timestamp()));
 response=pg_temp.checklist(task,'quality',4);perform pg_temp.qc('submit',jsonb_build_object('id',inspection,'submission_id',response,'findings','[]'::jsonb));perform pg_temp.actor(5);perform pg_temp.qc('decide',jsonb_build_object('id',inspection,'decision','approved'));
 response=pg_temp.checklist(task,'handover',actor);perform pg_temp.actor(3);perform pg_temp.fc('review_checklist',jsonb_build_object('task_id',task,'id',response,'approve',true));
end$$;
