insert into execution_ids values('new-trade',pg_temp.fc('create_task',jsonb_build_object('resource_id',(select id from execution_ids where key='new-resource'),'code','replacement-trade','description','Explicit approved wider construction scope','start',public.read_work_order((select id from execution_ids where key='work'))->>'start','end',public.read_work_order((select id from execution_ids where key='work'))->>'end')));
select pg_temp.cc('link_task',jsonb_build_object('task_id',(select id from execution_ids where key='new-trade'),'purpose','construction_milestone'));
insert into execution_ids values('replacement-milestone',pg_temp.cc('milestone.create',jsonb_build_object('task_id',(select id from execution_ids where key='new-trade'),'variation_id',(select id from execution_ids where key='priced-variation'),'code','M-REPLACED','trade','painting','scope','{"replacement":"Explicit approved wider construction scope"}'::jsonb,'measurements','{"wall_area":"15.0000"}'::jsonb)));
select pg_temp.cc('variation.implement',jsonb_build_object('id',(select id from execution_ids where key='priced-variation'),'task_id',(select id from execution_ids where key='new-trade'),'predecessors',jsonb_build_array((select id from execution_ids where key='milestone'),(select id from execution_ids where key='milestone2'))));
reset role;select pg_temp.assert_true((select count(*)=2 from private.order_commercial_versions where order_id=(select id from execution_ids where key='order')),'Priced variation appends accepted commercial history instead of rewriting original scope');select pg_temp.assert_true((select count(*)=2 from private.construction_milestone_successors where variation_id=(select id from execution_ids where key='priced-variation')),'Explicit replacement relationships preserve both retired milestone references');
rollback to savepoint priced_variation;set local role authenticated;
select pg_temp.arrive((select id from execution_ids where key='trade'),1);select pg_temp.start_job((select id from execution_ids where key='trade'),1);
select pg_temp.actor(3);select pg_temp.cc('material.record',jsonb_build_object('id',(select id from execution_ids where key='material'),'task_id',(select id from execution_ids where key='trade'),'kind','received','quantity','5.0000','evidence_id',(select id from execution_ids where key='proof')));
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.cc('material.record',jsonb_build_object('id',(select id from execution_ids where key='material'),'task_id',(select id from execution_ids where key='trade'),'kind','consumed','quantity','6.0000','evidence_id',(select id from execution_ids where key='proof')))$q$,'23514'),'Materials cannot be consumed beyond actual receipt');
select pg_temp.cc('material.record',jsonb_build_object('id',(select id from execution_ids where key='material'),'task_id',(select id from execution_ids where key='trade'),'kind','consumed','quantity','4.0000','evidence_id',(select id from execution_ids where key='proof')));
select pg_temp.cc('material.record',jsonb_build_object('id',(select id from execution_ids where key='material'),'task_id',(select id from execution_ids where key='trade'),'kind','returned','quantity','1.0000','evidence_id',(select id from execution_ids where key='proof')));
insert into execution_ids values('variation',pg_temp.cc('variation.propose',jsonb_build_object('scope','{"unapproved_extra_wall":true}'::jsonb,'cost_impact','0.00','time_impact_seconds',0,'evidence_id',(select id from execution_ids where key='proof'))));
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.cc('variation.implement',jsonb_build_object('id',(select id from execution_ids where key='variation'),'task_id',(select id from execution_ids where key='trade')))$q$,'23514'),'Unapproved variation cannot authorise work');
select pg_temp.actor(6);select pg_temp.cc('variation.customer',jsonb_build_object('id',(select id from execution_ids where key='variation'),'accept',false));
select pg_temp.actor(3);select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.cc('variation.authorize',jsonb_build_object('id',(select id from execution_ids where key='variation')))$q$,'42501'),'Rejected customer variation cannot be commercially authorised');
select pg_temp.arrive((select id from execution_ids where key='trade2'),2);select pg_temp.start_job((select id from execution_ids where key='trade2'),2);select pg_temp.finish_job((select id from execution_ids where key='trade2'),2);
select pg_temp.actor(1);select pg_temp.finish_job((select id from execution_ids where key='trade'),1);
select pg_temp.actor(5);select pg_temp.cc('milestone.inspect',jsonb_build_object('id',(select id from execution_ids where key='milestone'),'evidence_id',(select id from execution_ids where key='proof')));
select pg_temp.cc('milestone.inspect',jsonb_build_object('id',(select id from execution_ids where key='milestone2'),'evidence_id',(select id from execution_ids where key='proof2')));
select pg_temp.actor(7);select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.cc('milestone.accept',jsonb_build_object('id',(select id from execution_ids where key='milestone')))$q$,'42501'),'Other customer cannot accept site handover');
select pg_temp.actor(6);select pg_temp.cc('milestone.accept',jsonb_build_object('id',(select id from execution_ids where key='milestone')));select pg_temp.cc('milestone.accept',jsonb_build_object('id',(select id from execution_ids where key='milestone2')));select pg_temp.fc('customer_confirm','{"decision":"confirmed","comment":"Synthetic inspected handover"}');
select pg_temp.actor(5);select pg_temp.cc('ready');select pg_temp.fc('close_work');select pg_temp.cc('close');
select pg_temp.assert_true(public.read_service_operation((select id from execution_ids where key='operation'))->>'status'='closed','Construction shared QA, milestone acceptance, handover and closure complete');
reset role;select pg_temp.assert_true((select status='rejected' from private.construction_variations where id=(select id from execution_ids where key='variation')),'Rejected scope remains retained and unimplemented');
rollback;
